-- Run after deploying and adding project_url + svitlo_cron_secret to Vault.
-- The secret is generated by npm run keys. Never put it in this file or public config.
create extension if not exists pg_cron;
create extension if not exists pg_net;
select cron.schedule('svitlo-minute','* * * * *',$$
 select net.http_post(
  url := (select decrypted_secret from vault.decrypted_secrets where name='project_url') || '/functions/v1/svitlo-jobs',
  headers := jsonb_build_object('Content-Type','application/json','x-cron-secret',
    (select decrypted_secret from vault.decrypted_secrets where name='svitlo_cron_secret')),
  body := '{}'::jsonb, timeout_milliseconds := 60000
 );
$$);
